-- CPT assessment criteria transcribed from VATPRC_CPT_log.html.
CREATE TABLE public.exam_record (
    id uuid PRIMARY KEY,
    instructor_id uuid NOT NULL REFERENCES public."user"(id),
    trainee_id uuid NOT NULL REFERENCES public."user"(id),
    level text NOT NULL CHECK (level IN ('S1', 'S2', 'S3', 'C1')),
    start_at timestamptz NOT NULL,
    end_at timestamptz NOT NULL CHECK (end_at > start_at),
    examiners jsonb NOT NULL,
    sheet_filing_id uuid NOT NULL UNIQUE REFERENCES public.sheet_filing(id),
    created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ix_exam_record_trainee ON public.exam_record (trainee_id, start_at DESC);
CREATE INDEX ix_exam_record_instructor ON public.exam_record (instructor_id);




